/**
 * Driftwood – code installer (section E)
 * ---------------------------------------------------------------------------
 * GENERATED by tools_gen_install.py from src/script_includes/*.js – do not edit
 * the embedded scripts here; edit the sources and regenerate.
 *
 * Run in: System Definition > Scripts - Background
 *   - Script scope dropdown: global
 *   - Application picker (top banner): Driftwood
 *
 * DRY_RUN = true  (default) reports what it would do; changes nothing.
 * DRY_RUN = false creates missing script includes and properties.
 * UPDATE_EXISTING = true also overwrites existing script includes / property
 *                  values that differ from the embedded version (re-deploy).
 *
 * Installs: script includes ConfigNowConfig, ConfigNowCollector, ConfigNowWriter
 *           (Accessible from: this application scope only)
 *           routing properties x_2160899_driftw_0.table.<category>
 * ES3-safe.
 */
(function () {
    var DRY_RUN = true;
    // Script scope guard: in an app scope, every table and API this script
    // touches is added to that app's cross-scope privileges, even in a dry run.
    var curScope = String(typeof gs.getCurrentScopeName == 'function' ? gs.getCurrentScopeName() : 'rhino.global');
    if (curScope != 'rhino.global' && curScope != 'global') {
        gs.info('ABORT: set the script scope (Scripts - Background) to global and run again. Current script scope: ' + curScope + '. Nothing was read or written.');
        return;
    }
    var UPDATE_EXISTING = false;
    var SCOPE = 'x_2160899_driftw_0';

    var SCRIPT_INCLUDES = [
/*@@SCRIPT_INCLUDES@@*/
    ];
    var PROPERTIES = [
/*@@PROPERTIES@@*/
    ];

    var out = [], warnings = 0, n = { created: 0, updated: 0, same: 0, differs: 0 };
    function log(m) { out.push(m); }
    function warn(m) { warnings++; out.push('  !! ' + m); }

    var app = new GlideRecord('sys_scope');
    if (!app.get('scope', SCOPE)) { gs.info('ABORT: scope ' + SCOPE + ' not found'); return; }
    var appId = app.getUniqueValue();
    var pickerOk = gs.getCurrentApplicationId() == appId;
    log('=== Driftwood code installer (' + (DRY_RUN ? 'DRY RUN – nothing will change' : 'LIVE') + (UPDATE_EXISTING ? ', update existing' : '') + ') ===');
    log('App: ' + app.getValue('name') + ' [' + SCOPE + ']   Application picker: ' + (pickerOk ? 'OK' : 'NOT Driftwood'));
    if (!pickerOk) {
        if (!DRY_RUN) { gs.info(out.join('\n') + '\nABORT: set the application picker to Driftwood, then re-run.'); return; }
        warn('Application picker is not Driftwood – a live run would abort.');
    }

    /* ---- Script includes ---- */
    for (var i = 0; i < SCRIPT_INCLUDES.length; i++) {
        var si = SCRIPT_INCLUDES[i];
        var gr = new GlideRecord('sys_script_include');
        gr.addQuery('name', si.name);
        gr.addQuery('sys_scope', appId);
        gr.setLimit(1);
        gr.query();
        var lines = si.script.split('\n').length;
        if (gr.next()) {
            if (gr.getValue('script') == si.script) { log('SI     ' + si.name + '  up to date (' + lines + ' lines)'); n.same++; continue; }
            if (!UPDATE_EXISTING) { warn('SI ' + si.name + ' exists but differs from this version – set UPDATE_EXISTING = true to overwrite'); n.differs++; continue; }
            log('SI     ' + si.name + '  UPDATE (' + lines + ' lines)');
            if (!DRY_RUN) { gr.setValue('script', si.script); gr.setValue('description', si.description); gr.update(); }
            n.updated++;
            continue;
        }
        log('SI     ' + si.name + '  CREATE (' + lines + ' lines, this application scope only)');
        if (!DRY_RUN) {
            gr.initialize();
            gr.setValue('name', si.name);
            gr.setValue('script', si.script);
            gr.setValue('description', si.description);
            gr.setValue('active', true);
            gr.setValue('client_callable', false);
            if (gr.isValidField('access')) gr.setValue('access', 'package_private');
            var id = gr.insert();
            if (!id) { warn('Insert failed: ' + si.name); continue; }
            var chk = new GlideRecord('sys_script_include');
            if (chk.get(id)) {
                if (chk.getValue('sys_scope') != appId) warn(si.name + ' was created outside the app (' + chk.getDisplayValue('sys_scope') + ')');
                log('       api_name: ' + chk.getValue('api_name'));
            }
        }
        n.created++;
    }

    /* ---- Properties ---- */
    for (var p = 0; p < PROPERTIES.length; p++) {
        var pr = PROPERTIES[p];
        var g = new GlideRecord('sys_properties');
        g.addQuery('name', pr.name);
        g.setLimit(1);
        g.query();
        if (g.next()) {
            if (g.getValue('value') == pr.value) { log('PROP   ' + pr.name + ' = ' + pr.value + '  (already set)'); n.same++; continue; }
            if (!UPDATE_EXISTING) { warn('PROP ' + pr.name + ' is "' + g.getValue('value') + '" (want "' + pr.value + '") – set UPDATE_EXISTING = true to change'); n.differs++; continue; }
            log('PROP   ' + pr.name + '  UPDATE -> ' + pr.value);
            if (!DRY_RUN) { g.setValue('value', pr.value); g.update(); }
            n.updated++;
            continue;
        }
        log('PROP   ' + pr.name + ' = ' + pr.value + '  CREATE');
        if (!DRY_RUN) {
            g.initialize();
            g.setValue('name', pr.name);
            g.setValue('value', pr.value);
            g.setValue('type', 'string');
            g.setValue('description', pr.description);
            var pid = g.insert();
            if (!pid) { warn('Insert failed: ' + pr.name); continue; }
            var pc = new GlideRecord('sys_properties');
            if (pc.get(pid) && pc.getValue('sys_scope') != appId) warn(pr.name + ' was created outside the app (' + pc.getDisplayValue('sys_scope') + ')');
        }
        n.created++;
    }

    /* ---- Target tables exist? ---- */
    var targets = {};
    for (var q = 0; q < PROPERTIES.length; q++) targets[PROPERTIES[q].value] = true;
    for (var t in targets) if (!new GlideRecord(t).isValid()) warn('Routing target table ' + t + ' does not exist');

    log('--- Summary ---');
    log((DRY_RUN ? 'Would create: ' : 'Created: ') + n.created + ', ' + (DRY_RUN ? 'would update: ' : 'updated: ') + n.updated +
        ', unchanged: ' + n.same + ', differ (not touched): ' + n.differs + '.  Warnings: ' + warnings);
    if (DRY_RUN) log('Set DRY_RUN = false and run again to apply.');
    else log('Next (F01): run the collector test in Scripts - Background with the SCRIPT SCOPE set to Driftwood.');
    gs.info(out.join('\n'));
})();
